-- name and images untouched (ON CONFLICT DO NOTHING) - they were priced
-- by hand and must not be overwritten by supplier data. They still get
-- linked into the new category tree.

BEGIN;

DELETE FROM public.product_images a
  USING public.product_images b
 WHERE a.product_id = b.product_id
   AND a.url = b.url
   AND a.ctid > b.ctid;

CREATE UNIQUE INDEX IF NOT EXISTS product_images_product_url_key
  ON public.product_images (product_id, url);
CREATE UNIQUE INDEX IF NOT EXISTS products_sku_key
  ON public.products (sku);

